import Button from '../button/Base.mjs';

Neo.create(Button, {
    iconCls: 'fa fa-home',
    text   : 'Home'
});

import Button from '../button/Base.mjs';

Neo.create({
    module : Button,
    iconCls: 'fa fa-home',
    text   : 'Home'
});

Neo.create('Neo.button.Base' {
    iconCls: 'fa fa-home',
    text   : 'Home'
});

Neo.create({
    className: 'Neo.button.Base',
    iconCls  : 'fa fa-home',
